/**
 * 順豐站點坐標快照（v2.2.2 新增）
 *
 * 點解要有呢個檔案：站點坐標原本只靠 sfSync 每日同步先攞到，
 * 新部署／同步失敗時 GPS 最近站點會完全搵唔到（種子資料本身冇坐標）。
 * 所以呢度將 2026-09-30 從順豐官方 API 抓返嘅完整坐標快照落碼，
 * boot 時回填晒啲 lat IS NULL 嘅行；之後 sfSync 照舊每日更新，唔會被快照覆蓋。
 *
 * 格式：[region, type, name（已轉繁）, lng, lat, phone, serviceTime]
 * 自動生成，唔好手改。生成日期：2026-09-30。
 */
export type SfStationCoordRow = readonly [
  region: "HK" | "MO",
  type: "SF_STATION" | "SERVICE_POINT" | "SF_LOCKER",
  name: string,
  lng: number,
  lat: number,
  phone: string,
  serviceTime: string,
];

